package eu.virac.vea_izi_vsrc.model.fileConvert;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import lombok.*;

@Setter
@Getter
@NoArgsConstructor
@ToString
@Entity
@Table(name = "ExcelRow")
public class ExcelRow {

	
	// Internal ID for ExcelRow.
    // Auto generated by DB, NOT used for import/export logic.
    @Id
    @GeneratedValue(strategy = GenerationType.AUTO)
    @Column(name = "idExcelRow")
    @Setter(AccessLevel.NONE)
    private long idExcelRow;

    // ID of the original entity (Category, KPI, Task, etc.)
    // This is ONLY informational during export.
    // Import NEVER uses this ID bcs DB generates new IDs.
    @Column(name = "entityId")
    private Long entityId;

    @Column(name = "col1")
    private String col1;

    @Column(name = "col2")
    private String col2;

    @Column(name = "col3")
    private String col3;

    @Column(name = "col4")
    private String col4;

    @Column(name = "col5")
    private String col5;

    
    public ExcelRow(Long entityId, String col1, String col2, String col3, String col4, String col5) {
        setEntityId(entityId);
        setCol1(col1); 
        setCol2(col2);
        setCol3(col3);
        setCol4(col4);
        setCol5(col5);
    }
}
